#pragma once#include <IXmlNode.h>#include <MSXML/msxml.tlh>#include <macros/AutoRestore.h>#include "MSXML/msxml.tlh"void Flush( MSXML::IXMLDOMDocumentPtr &xmlDoc, MSXML::IXMLDOMElementPtr root, tXmlNodePtr_ pNode, LPSTR pszOffset, size_t sizeOffset ){  MSXML::IXMLDOMTextPtr text0;  if( root )  {    text0 = xmlDoc->createTextNode( "\n" );    root->appendChild( text0 );  }  const size_t len = strlen( pszOffset );  TAutoRestore<char> restoreOffset( pszOffset[len] );  if( root )    strcat_s( pszOffset, sizeOffset, "  ");  if( root )  {    MSXML::IXMLDOMTextPtr text2 = xmlDoc->createTextNode( pszOffset );    root->appendChild( text2 );  }  LPCSTR pszType = pNode->GetNodeType();  MSXML::IXMLDOMElementPtr curEl = xmlDoc->createElement( pszType );  if( root )    root->appendChild( curEl );  else    xmlDoc->appendChild( curEl );  for( tAttrsIterator_ itAttr = pNode->EnumAttrs(); itAttr; ++itAttr )  {    tAttrsIterator_::type_value::value_type &attr = *itAttr;    curEl->setAttribute( attr.szName.c_str(), attr.szValue.c_str() );  }  LPCSTR pData = pNode->GetData();  if( pData )  {    _bstr_t str(pData);    curEl->Puttext(str);  }  bool bWasChild = false;  for( tChildrenIterator_ itChildren = pNode->EnumChildren(); itChildren; ++itChildren )  {    Flush( xmlDoc, curEl, *itChildren, pszOffset, sizeOffset );    bWasChild = true;  }  if( !bWasChild )    return;  text0 = xmlDoc->createTextNode( "\n" );  curEl->appendChild( text0 );  text0 = xmlDoc->createTextNode( pszOffset );  curEl->appendChild( text0 );}